using System;using System.Linq;using UnityEngine;using OneWay.Battle3D;
public static class ReviewIdleShieldClearance {
 public static object Run(){var live=UnityEngine.Object.FindFirstObjectByType<NewPlayerAttackCombo>();var root=UnityEngine.Object.Instantiate(live.transform.Find("NewPlayer Visual").gameObject);root.hideFlags=HideFlags.HideAndDontSave;var go=new GameObject("Shield review camera");go.hideFlags=HideFlags.HideAndDontSave;var cam=go.AddComponent<Camera>();cam.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.24f,.26f,.29f);cam.fieldOfView=38;var rt=new RenderTexture(360,420,24);cam.targetTexture=rt;var tex=new Texture2D(1800,840,TextureFormat.RGB24,false);var previous=RenderTexture.active;Mesh baked=null;GameObject draw=null;
 try{root.transform.SetPositionAndRotation(new Vector3(1000,0,1000),Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;live.motions.idle.SampleAnimation(a.gameObject,0);var shield=root.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Shield4");shield.gameObject.SetActive(true);var originalPosition=shield.position;var original=shield.localRotation;var baseWorld=shield.rotation;var outward=Quaternion.FromToRotation(shield.right,root.transform.right)*baseWorld;var skin=root.GetComponentInChildren<SkinnedMeshRenderer>();baked=UnityEngine.Object.Instantiate(skin.sharedMesh);var v=baked.vertices;var w=baked.boneWeights;var matrices=skin.bones.Select((b,i)=>b.localToWorldMatrix*baked.bindposes[i]).ToArray();for(int i=0;i<v.Length;i++){var wt=w[i];var p=v[i];v[i]=matrices[wt.boneIndex0].MultiplyPoint3x4(p)*wt.weight0+matrices[wt.boneIndex1].MultiplyPoint3x4(p)*wt.weight1+matrices[wt.boneIndex2].MultiplyPoint3x4(p)*wt.weight2+matrices[wt.boneIndex3].MultiplyPoint3x4(p)*wt.weight3;}baked.vertices=v;baked.RecalculateNormals();baked.RecalculateBounds();draw=new GameObject("Shield review body");draw.hideFlags=HideFlags.HideAndDontSave;draw.AddComponent<MeshFilter>().sharedMesh=baked;draw.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;skin.enabled=false;var target=skin.bones.First(b=>b.name=="Hips").position+Vector3.up*.15f;var results=new System.Collections.Generic.List<object>();
 for(int col=0;col<5;col++){shield.rotation=outward;shield.position=originalPosition+root.transform.right*(col*.04f);results.Add(new{candidate=col,offset=(Quaternion.Inverse(original)*shield.localRotation).eulerAngles.ToString(),local=shield.localEulerAngles.ToString()});for(int row=0;row<2;row++){cam.transform.position=target+(row==0?new Vector3(-2.8f,1,3.5f):new Vector3(-3.5f,.5f,-2.8f));cam.transform.LookAt(target);cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,360,420),col*360,(1-row)*420);}}
 tex.Apply();System.IO.File.WriteAllBytes("Assets/3DBattle/Authoring~/IdleShieldClearance.png",tex.EncodeToPNG());return results;
 }finally{RenderTexture.active=previous;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);if(draw)UnityEngine.Object.DestroyImmediate(draw);if(baked)UnityEngine.Object.DestroyImmediate(baked);}}
}


